CREATE TABLE IF NOT EXISTS team_schedule_guard(id BIGINT PRIMARY KEY CHECK(id=1),sequence BIGINT NOT NULL CHECK(sequence>=0),clock_highwater BIGINT NOT NULL);
INSERT INTO team_schedule_guard(id,sequence,clock_highwater) VALUES(1,0,0) ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS team_schedules(id TEXT PRIMARY KEY,team_id TEXT NOT NULL REFERENCES identity_organizations(id),project_id TEXT NOT NULL REFERENCES tenant_projects(id),revision BIGINT NOT NULL CHECK(revision>0),execution_revision BIGINT NOT NULL CHECK(execution_revision>0),grant_id TEXT NOT NULL,paused BIGINT NOT NULL CHECK(paused IN(0,1)),deleted BIGINT NOT NULL CHECK(deleted IN(0,1)),next_run BIGINT NOT NULL,active_occurrence_id TEXT,payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS team_schedule_due ON team_schedules(paused,deleted,next_run);
CREATE TABLE IF NOT EXISTS team_schedule_grants(id TEXT PRIMARY KEY,schedule_id TEXT NOT NULL REFERENCES team_schedules(id),team_id TEXT NOT NULL REFERENCES identity_organizations(id),project_id TEXT NOT NULL REFERENCES tenant_projects(id),identity_id TEXT NOT NULL REFERENCES identity_subjects(id),execution_revision BIGINT NOT NULL CHECK(execution_revision>0),active BIGINT NOT NULL CHECK(active IN(0,1)),payload TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS team_schedule_occurrences(id TEXT PRIMARY KEY,schedule_id TEXT NOT NULL REFERENCES team_schedules(id),team_id TEXT NOT NULL REFERENCES identity_organizations(id),project_id TEXT NOT NULL REFERENCES tenant_projects(id),sequence BIGINT NOT NULL UNIQUE CHECK(sequence>0),execution_revision BIGINT NOT NULL CHECK(execution_revision>0),grant_id TEXT NOT NULL REFERENCES team_schedule_grants(id),reserved_run_id TEXT NOT NULL UNIQUE,run_id TEXT UNIQUE,creation_key TEXT NOT NULL UNIQUE,status TEXT NOT NULL CHECK(status IN('claimed','queued','running','completed','failed','cancelled','unknown','blocked')),due_at BIGINT NOT NULL,claimed_at BIGINT NOT NULL,last_checked BIGINT NOT NULL DEFAULT 0,completed_at BIGINT,request TEXT NOT NULL,error TEXT);
CREATE INDEX IF NOT EXISTS team_schedule_history ON team_schedule_occurrences(schedule_id,sequence);
CREATE INDEX IF NOT EXISTS team_schedule_reconcile ON team_schedule_occurrences(status,last_checked,sequence);
CREATE TABLE IF NOT EXISTS team_schedule_operations(actor_id TEXT NOT NULL REFERENCES identity_subjects(id),team_id TEXT NOT NULL REFERENCES identity_organizations(id),project_id TEXT NOT NULL REFERENCES tenant_projects(id),intent_key TEXT NOT NULL,request_sha TEXT NOT NULL,receipt TEXT NOT NULL,PRIMARY KEY(actor_id,team_id,intent_key));
